// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonAdmin) public {
        vm.assume(nonAdmin != address(this));
        address ownerBefore = c.owner();
        vm.prank(nonAdmin);
        (bool success, bytes memory retData) = address(c).call(abi.encodeWithSignature("setOwner(address)", address(0x1234)));
        address ownerAfter = c.owner();
        bool pass = (ownerAfter == ownerBefore);
        assertTrue(pass);
    }
}
